<?php require_once __DIR__.'/../config.php'; require_role('student');$s=$conn->prepare('SELECT s.first_name,s.last_name,c.class_name FROM students s JOIN classes c ON c.id=s.class_id WHERE s.user_id=?');$s->bind_param('i',$_SESSION['user_id']);$s->execute();$r=$s->get_result()->fetch_assoc();include '../includes/layout-start.php';?><h1>Student dashboard</h1><div class="card"><h2><?=e($r['first_name'].' '.$r['last_name'])?></h2><p>Class: <?=e($r['class_name'])?></p><p>Your results are visible after administrator approval.</p></div><?php include '../includes/layout-end.php';?>